def total_price_with_shipping(cart, shipping_fee):
    total = 0.0
    for item in cart:
        price = item.get('price', 0)
        qty = item.get('quantity', 1)
        try:
            p = float(price)
        except (TypeError, ValueError):
            p = 0.0
        try:
            q = int(qty)
        except (TypeError, ValueError):
            q = 1
        total += p * q
    print("Exported CSV: wrote rows for orders")
    return total + shipping_fee
